interface Component { operation(): string }
class ConcreteComponent implements Component {
  operation(){ return "core" }
}
class Wrapper implements Component {
  constructor(private wrappee: Component) {}
  operation(){ return `decorated:${this.wrappee.operation()}` }
}

interface Service { fetch(id: number): Promise<string> }
class BaseService implements Service { async fetch(id:number){ return `data ${id}` } }
class AuthWrapper implements Service { constructor(private svc:Service){} async fetch(id:number){ /* auth */ return this.svc.fetch(id) } }
class CacheWrapper implements Service { constructor(private svc:Service){} async fetch(id:number){ /* cache */ return this.svc.fetch(id) } }

// Version A: small composable wrappers
interface Notifier { send(msg: string): void }
class BasicNotifier implements Notifier { send(msg:string){ console.log(msg) } }
class EmailWrapper implements Notifier { constructor(private n:Notifier){} send(msg:string){ /* send email */ this.n.send(msg) } }
class SmsWrapper implements Notifier { constructor(private n:Notifier){} send(msg:string){ /* send sms */ this.n.send(msg) } }

// Version B: single configurable class
class MultiChannelNotifier implements Notifier {
  constructor(private sendEmail:boolean, private sendSms:boolean) {}
  send(msg:string){
    if(this.sendEmail){ /* send email */ }
    if(this.sendSms){ /* send sms */ }
    console.log(msg)
  }
}
